module Parent() {
  module Child() {
    export const n: number = 3
  }
  instance Kid = Child()
  line L = segment(start: (0, 0), end: (@Kid::n, 4))
  export const length: number = @L.length
  export point P = coordinate(x: @length, y: @L.endPoint.y)
}
instance Copy = Parent()
const length: number = @Copy::length
point Root = coordinate(x: @length * 2, y: 1)
point Sentinel = coordinate(x: -101, y: 103)

