module Parent() {
  module Child(v: number) {
    export const n: number = @v * 2
  }
  instance Off(enabled: false) = Child(v: 3)
  instance On = Child(v: 7)
  export point Bad = coordinate(x: @Off::n, y: 1)
  export point Good = coordinate(x: @On::n, y: 2)
}
instance Copy = Parent()
point Sentinel = coordinate(x: -101, y: 103)
module Independent() {
  module Child() {
    export const n: number = 14
  }
  instance On = Child()
  export point Good = coordinate(x: @On::n, y: 2)
}
instance Safe = Independent()
